-- Full coupon + amortization schedule for the 12 ON bonds (DetallePagos.xlsx).
-- Replaces the partial schedule from 0006/0007, which carried coupons only:
-- without a principal repayment the cash flows never return the capital, so
-- YTM and duration had nothing to solve for.
--
-- Amortization rows are typed AMORT. They used to be inferred from SELL or from
-- the description text; the type is explicit now.
--
-- The delete clears every transaction attached to these bonds. That is safe here:
-- the bonds were bought 2026-08-20 and the earliest scheduled payment is
-- 2026-09-05, so none of these rows is a payment already received.

delete from transactions where asset_id in (select id from assets where ticker in ('CICAO', 'GYC5O', 'HJCIO', 'IRCPO', 'MCC1O', 'MCC3O', 'MGCRO', 'OT42O', 'PLC3O', 'PLC4O', 'VSCVO', 'ZZC1O') and id like 'bond-%');
delete from recurring_incomes where asset_id in (select id from assets where ticker in ('CICAO', 'GYC5O', 'HJCIO', 'IRCPO', 'MCC1O', 'MCC3O', 'MGCRO', 'OT42O', 'PLC3O', 'PLC4O', 'VSCVO', 'ZZC1O') and id like 'bond-%');

on conflict (id) do update set
  date = excluded.date,
  description = excluded.description,
  amount = excluded.amount,
  type = excluded.type,
  asset_id = excluded.asset_id;
